// FILE: src/data/news-competitor-releases.data.js
// ============================================================
// BERITA RILIS PRODUK KOMPETITOR — dunia nyata 2000-2026.
// Dipakai NewsSystem untuk menampilkan berita internasional
// saat kompetitor merilis produk / mengalami peristiwa kunci,
// mengikuti waktu di dalam game (tahun & bulan game).
//
// Field per entri:
//   cid         → id kompetitor (harus ada di competitors.data.js)
//   year, month → kapan berita muncul (bulan pengumuman/peluncuran)
//   day         → opsional; kalau kosong, hari muncul diacak stabil (3-26)
//   product     → nama produk / peristiwa
//   tone        → 'positive' | 'mixed' | 'negative'
//   tags        → untuk filter/pencarian
//   h, t        → headline & ringkasan (Bahasa Indonesia)
//   h_en, t_en  → headline & ringkasan (English)
//   approx      → true kalau BULAN-nya perkiraan (tahun & peristiwa nyata)
//   speculative → true kalau belum terkonfirmasi/masih bocoran
//
// Catatan: nama media (source) diambil otomatis dari outlet fiktif
// di news.data.js sesuai tahun. Peristiwa & produk mengacu dunia
// nyata; teks ditulis ulang ringkas, bukan kutipan.
// Entri hanya muncul selama kompetitor aktif di game
// (activeFromYear – activeToYear di competitors.data.js).
// ============================================================
