function _slug(s) {
    return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

// ID stabil & unik per entri (dipakai untuk dedup di save game).
COMPETITOR_RELEASE_NEWS.forEach(function (e) {
    e.id = 'crel_' + e.cid + '_' + e.year + '_' + e.month + '_' + _slug(e.product);
});

// Hari muncul stabil (3-26) bila `day` tidak diisi, supaya
// berita dalam satu bulan tidak menumpuk di satu hari.
export function getReleaseDay(entry) {
    if (entry.day) return entry.day;
    var h = 0, s = entry.id;
    for (var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 9973;
    return 3 + (h % 24);
}

export function getCompetitorReleasesForMonth(year, month) {
    return COMPETITOR_RELEASE_NEWS.filter(function (e) {
        return e.year === year && e.month === month;
    });
}

export function getCompetitorReleasesForCompetitor(cid) {
    return COMPETITOR_RELEASE_NEWS.filter(function (e) { return e.cid === cid; });
}

export function validateCompetitorReleaseNews() {
    var issues = [];
    var seen = {};
    COMPETITOR_RELEASE_NEWS.forEach(function (e) {
        var comp = getCompetitorById(e.cid);
        if (!comp) { issues.push('Kompetitor tidak ada: ' + e.cid); return; }
        if (e.year < comp.activeFromYear) issues.push(e.id + ': sebelum kompetitor aktif');
        if (comp.activeToYear !== null && e.year > comp.activeToYear) issues.push(e.id + ': setelah kompetitor keluar');
        if (e.month < 1 || e.month > 12) issues.push(e.id + ': bulan invalid');
        if (!e.h || !e.t || !e.h_en || !e.t_en) issues.push(e.id + ': teks ID/EN belum lengkap');
        if (['positive', 'mixed', 'negative'].indexOf(e.tone) === -1) issues.push(e.id + ': tone invalid');
        if (seen[e.id]) issues.push('Duplikat: ' + e.id);
        seen[e.id] = true;
    });
    if (issues.length) {
        console.warn('[news-competitor-releases] ' + issues.length + ' masalah:');
        issues.forEach(function (i) { console.warn('  - ' + i); });
    } else {
        console.info('[news-competitor-releases] Validasi OK. ' + COMPETITOR_RELEASE_NEWS.length + ' entri.');
    }
    return issues;
}
